const input = $input.first().json.body ?? $input.first().json;
const invoice = input.invoice;
if (!input.delivery_id || !input.correlation_id || !invoice?.invoice_id || typeof invoice.amount !== 'number' || invoice.amount <= 0 || !invoice.currency) throw new Error('Invalid invoice intake');
if (Object.hasOwn(invoice, 'approved')) throw new Error('Approval must be submitted to invoice-approve, not invoice-intake');
return [{ json: { delivery_id: input.delivery_id, correlation_id: input.correlation_id, invoice, idempotency_prefix: `invoice:${invoice.invoice_id}:${input.delivery_id}` } }];
